              <ui.Box flexShrink={0}>
                <ui.Text>{cut(firstLine(r.failure.where), Math.max(16, Math.floor(inner / 2)))}</ui.Text>
              </ui.Box>
            ) : null}
            {r.failure.where && r.failure.why ? <ui.Text dimColor>·</ui.Text> : null}
            {r.failure.why ? (
              <ui.Box flexShrink={1}>
